INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('e5d1f9a5-86b9-41d5-a258-8f21cd1e83e6'::uuid, 'card_description', 'Built in the 6th century BC and used for nearly 500 years, this Hampshire hillfort was so intensively researched that it became the defining type-site for understanding hillforts across Wessex.', 'In 1859, workers at Danebury cleared an Iron Age pit 2 metres deep whose purpose they could not ascertain. In 1974, a grain pit at this Hampshire hillfort gave up a meteorite.', 'teaser-card-s021:e5d1f9a5-86b9-41d5-a258-8f21cd1e83e6:card_description', 'teaser-card-s021 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'c0b786901850bec6fc4a788a23ec4f52c6f9fad211039a9c6d661cf94425476b|7e3eb0f5d51b00429050009b54414a29fdbc5fb424fd21fae9862fa16b924646|7e3eb0f5d51b00429050009b54414a29fdbc5fb424fd21fae9862fa16b924646', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1859, workers at Danebury cleared an Iron Age pit 2 metres deep whose purpose they could not ascertain. In 1974, a grain pit at this Hampshire hillfort gave up a meteorite."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in 1859 workers at Danebury cleared a pit [S4, S5]; the pit was Iron Age [S5]; the pit was 2 metres deep [S5]; the workers could not ascertain the pit''s purpose [S5]; in 1974 a grain pit at the hillfort gave up a meteorite [S8]; Danebury is a hillfort in Hampshire [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Danebury is an Iron Age hillfort in Hampshire, England (what kind of place, and where) [SUPPORTED: https://en.wikipedia.org/wiki/Danebury]; In 1859 workers at Danebury cleared out an Iron Age pit (first excavation, November 1859) [SUPPORTED: https://en.wikipedia.org/wiki/Danebury]; The workers cleared an Iron Age pit [SUPPORTED: https://en.wikipedia.org/wiki/Danebury]; The pit was 2 metres deep [SUPPORTED: https://en.wikipedia.org/wiki/Danebury]; The workers could not ascertain the pit''s purpose [SUPPORTED: https://en.wikipedia.org/wiki/Danebury]; In 1974 a meteorite was found in a grain pit at the Danebury hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Danebury]"}]'::jsonb),
    ('e69a6a9f-9adf-4927-833d-5d5d0d0d7112'::uuid, 'card_description', 'Founded 443 BC as a Panhellenic colony by Athens and Sybaris exiles. Herodotus settled here; Hippodamus laid out its grid streets; Protagoras wrote its constitution.', 'Founded in 443 BC as a colony of Athens with exiles from Sybaris, Thurii rose on the Gulf of Taranto near or on the site of that renowned city, and had an active mint.', 'teaser-card-s021:e69a6a9f-9adf-4927-833d-5d5d0d0d7112:card_description', 'teaser-card-s021 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '6224009f098bbef5762a3d22345eba688b36162be2a0bba45e3ec0ea121cb4d3|dc849e096e89e026644b260010c117d86427e9869e624e8afa10340730b916a1|dc849e096e89e026644b260010c117d86427e9869e624e8afa10340730b916a1', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Founded in 443 BC as a colony of Athens with exiles from Sybaris, Thurii rose on the Gulf of Taranto near or on the site of that renowned city, and had an active mint."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Thurii was founded in 443 BC [S2]; it was founded as a colony of Athens [S2]; it was founded with exiles from Sybaris [S2]; it lay on the Gulf of Taranto [S1]; it lay near or on the site of the renowned city of Sybaris [S1]; it had an active mint [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Thurii was an ancient Greek city (settlement) on the Gulf of Taranto [SUPPORTED: https://en.wikipedia.org/wiki/Thurii]; Thurii lay on the Gulf of Taranto near or on the site of the renowned city of Sybaris [SUPPORTED: https://en.wikipedia.org/wiki/Thurii]; Thurii was founded in 443 BC [SUPPORTED: https://en.wikipedia.org/wiki/Thurii]; Thurii was founded as a colony of Athens [SUPPORTED: https://en.wikipedia.org/wiki/Thurii]; The colony was founded with exiles from Sybaris [SUPPORTED: https://en.wikipedia.org/wiki/Thurii]; Sybaris was a renowned city [SUPPORTED: https://en.wikipedia.org/wiki/Thurii]; Thurii had an active mint [SUPPORTED: https://en.wikipedia.org/wiki/Thurii]"}]'::jsonb),
    ('e6b90e74-f7c5-40fa-846f-6ffab5ac8beb'::uuid, 'card_description', NULL, 'A long, flat ridge flanked by Wied Dalam and Wied Żembaq carries Ta'' Kaċċatura: underground cisterns and a rustic Roman villa that confirms a thriving olive oil industry.', 'teaser-card-s021:e6b90e74-f7c5-40fa-846f-6ffab5ac8beb:card_description', 'teaser-card-s021 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '23e445494c429ea8dea816aa731f5b287e8f5e2cb1851171eb4373f3e14ab400|6a16dfcd0b02d2f64583c4f16f1b49f45411c4fc3c4873b0d7c24b6975e9473f|6a16dfcd0b02d2f64583c4f16f1b49f45411c4fc3c4873b0d7c24b6975e9473f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A long, flat ridge flanked by Wied Dalam and Wied Żembaq carries Ta'' Kaċċatura: underground cisterns and a rustic Roman villa that confirms a thriving olive oil industry."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site stands on a ridge that is long and flat [S4]; the ridge is flanked by Wied Dalam and Wied Żembaq [S4]; the remains of Ta'' Kaċċatura rest on that ridge [S4]; the site includes underground cisterns [S2]; the site includes a rustic Roman villa [S2]; the villa confirms a thriving olive oil industry [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ta'' Kaccatura is an archaeological complex (what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_Ka%C4%8B%C4%8Batura]; Ta'' Kaccatura lies on the outskirts of Birzebbuga, in southern Malta [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_Ka%C4%8B%C4%8Batura]; The site has a rustic Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_Ka%C4%8B%C4%8Batura]; The site has underground cisterns [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_Ka%C4%8B%C4%8Batura]; The remains rest on a long, flat ridge [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_Ka%C4%8B%C4%8Batura]; The ridge is flanked by the valleys Wied Dalam and Wied Zembaq [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_Ka%C4%8B%C4%8Batura]; The villa confirms a thriving olive oil industry [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_Ka%C4%8B%C4%8Batura]"}]'::jsonb),
    ('e6e02f02-3df6-44e3-ada1-7f41b60617a5'::uuid, 'card_description', 'Ruins include remains of the walls and the pre-Roman necropolis was partially excavated in 1882.', 'On the Via Appia, near where the road turns east into the mountains, Calatia was taken by the Samnites in 313 BC and again in 311 BC. In 59 BC Caesar established a colony here.', 'teaser-card-s021:e6e02f02-3df6-44e3-ada1-7f41b60617a5:card_description', 'teaser-card-s021 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '2a8219a79b3996e9391d8ee3d04ded9047857ced5f59973ca14f4bcacc673ac2|e6982336bf41e8c180b6be74a1858d0f6aeb4d8bbbd8275b684d2f394309537c|e6982336bf41e8c180b6be74a1858d0f6aeb4d8bbbd8275b684d2f394309537c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the Via Appia, near where the road turns east into the mountains, Calatia was taken by the Samnites in 313 BC and again in 311 BC. In 59 BC Caesar established a colony here."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Calatia lay on the Via Appia [S1, S2]; it lay near where the road turns east into the mountains [S4]; it was taken by the Samnites in 313 BC [S5]; it was taken by the Samnites again in 311 BC [S5]; in 59 BC Caesar established a colony there [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Calatia was an ancient town of Campania, Italy, on the Via Appia [SUPPORTED: https://en.wikipedia.org/wiki/Calatia]; Calatia lay on the Via Appia [SUPPORTED: https://en.wikipedia.org/wiki/Calatia]; Calatia lay near the point where the Via Appia turns east and enters the mountains [SUPPORTED: https://en.wikipedia.org/wiki/Calatia]; Calatia was taken by the Samnites in 313 BC [SUPPORTED: https://en.wikipedia.org/wiki/Calatia]; The Samnites took Calatia again in 311 BC [SUPPORTED: https://en.wikipedia.org/wiki/Calatia]; In 59 BC Caesar established a colony at Calatia [SUPPORTED: https://en.wikipedia.org/wiki/Calatia]"}]'::jsonb),
    ('e7623642-d009-4d1f-8f0e-fa03a89be90e'::uuid, 'card_description', 'An 8-kilometre cave with chambers large enough to be called "cathedrals," used by humans since 5000 BC. One of the longest caves in the Pyrenees.', 'Deep in the limestone of Cap de la Lesse, the Grotte de Lombrives stretches for 8 km, one of three caves in the mountain. It connects with Niaux, yet neither reaches Sabart.', 'teaser-card-s021:e7623642-d009-4d1f-8f0e-fa03a89be90e:card_description', 'teaser-card-s021 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '24ad24e8e2f6260ef01bb77bbbf46fbeb67deec751d4267ad2084e3ada81c2e7|161c0fdcdf3a7a1308892d3679061291eacfcc4d40db9fe7de6999a249456bb5|161c0fdcdf3a7a1308892d3679061291eacfcc4d40db9fe7de6999a249456bb5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Deep in the limestone of Cap de la Lesse, the Grotte de Lombrives stretches for 8 km, one of three caves in the mountain. It connects with Niaux, yet neither reaches Sabart."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the cave lies inside the limestone of Cap de la Lesse [S3]; the Grotte de Lombrives is 8 km long [S2]; it is one of three caves in the mountain [S4]; it is connected with Niaux [S5]; neither Lombrives nor Niaux is connected with Sabart [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Grotte de Lombrives is a large natural cavern (cave) in Ariege, southwestern France [SUPPORTED: https://en.wikipedia.org/wiki/Lombrives]; The cave lies inside a limestone mountain named Cap de la Lesse [SUPPORTED: https://en.wikipedia.org/wiki/Lombrives]; The cave is 8 km long [SUPPORTED: https://www.showcaves.com/english/fr/showcaves/Lombrives.html]; Lombrives is one of three caves in the mountain (with Niaux and Sabart) [SUPPORTED: https://en.wikipedia.org/wiki/Lombrives]; Lombrives connects with Niaux [SUPPORTED: https://en.wikipedia.org/wiki/Lombrives]; Neither Lombrives nor Niaux is connected with Sabart [SUPPORTED: https://en.wikipedia.org/wiki/Lombrives]"}]'::jsonb),
    ('e79d32d8-f764-4a10-94eb-466f822f1968'::uuid, 'card_description', 'An 11th-millennium BC rock shelter containing burned bones of pygmy hippos alongside human tools. If the link holds, humans drove these mini-hippos to extinction.', 'At Aetokremnos, the Cliff of the eagles near Limassol, pygmy hippo bones make up 74% of the bones in the rock shelter. Yet fallow deer and pig lie there too, and their presence is puzzling.', 'teaser-card-s021:e79d32d8-f764-4a10-94eb-466f822f1968:card_description', 'teaser-card-s021 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '73e0b723fba08531d26c10b6898345a3e4bcd3cb028d56d945ce4c81b767f124|88ab5fca169ff8f77b4ea6ef52b407b52d0ebfa33ef41f7b3dfc3a4e1d336b33|88ab5fca169ff8f77b4ea6ef52b407b52d0ebfa33ef41f7b3dfc3a4e1d336b33', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Aetokremnos, the Cliff of the eagles near Limassol, pygmy hippo bones make up 74% of the bones in the rock shelter. Yet fallow deer and pig lie there too, and their presence is puzzling."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is called Aetokremnos [S1]; the name means Cliff of the eagles [S2]; the site is near Limassol [S1]; the site is a rock shelter [S1]; pygmy hippo bones make up 74% of the bones at the site [S6]; fallow deer and pig bones are present at the site [S7]; the presence of fallow deer and pig is puzzling [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Aetokremnos is a rock shelter [SUPPORTED: https://en.wikipedia.org/wiki/Aetokremnos]; Aetokremnos is near Limassol (Cyprus) [SUPPORTED: https://en.wikipedia.org/wiki/Aetokremnos]; The name Aetokremnos means Cliff of the eagles [SUPPORTED: https://en.wikipedia.org/wiki/Aetokremnos]; Pygmy hippo bones make up 74% of the bones at the site [SUPPORTED: https://en.wikipedia.org/wiki/Aetokremnos]; Fallow deer bones are found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Aetokremnos]; Pig bones are found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Aetokremnos]; The presence of fallow deer and pig at the site is puzzling (an open question) [SUPPORTED: https://en.wikipedia.org/wiki/Aetokremnos]"}]'::jsonb),
    ('e7ee7c00-1b94-4ff8-832e-7af0323bd3aa'::uuid, 'card_description', 'Ocriticum was an Italic and Roman town, the ruins of which are located in the comune of Cansano.', 'In Abruzzo, pilgrims, wayfarers and shepherds stopped at Ocriticum to venerate its divinities. Its first temple, from the end of the 4th century BC, had a sacred garden around its entrance.', 'teaser-card-s021:e7ee7c00-1b94-4ff8-832e-7af0323bd3aa:card_description', 'teaser-card-s021 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'e82e3018b93fb2c5a5461fb9d97491e57036d27a38983fb0537ff262398d8e41|9d9d673b60848c896e3bfe4ff0612dd0f2b23fc987f51fcdaf9b7e6548efd1cb|9d9d673b60848c896e3bfe4ff0612dd0f2b23fc987f51fcdaf9b7e6548efd1cb', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Abruzzo, pilgrims, wayfarers and shepherds stopped at Ocriticum to venerate its divinities. Its first temple, from the end of the 4th century BC, had a sacred garden around its entrance."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ocriticum is in Abruzzo [S1]; pilgrims, wayfarers and shepherds stopped at Ocriticum [S2]; they stopped there to venerate the divinities [S2]; the site had a first temple [S3]; the first temple dates to the end of the 4th century BC [S3]; a sacred garden lay around the temple''s entrance [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ocriticum is a sanctuary site of temples and divinities (an Italic and Roman town with a large sacred area) [SUPPORTED: https://en.wikipedia.org/wiki/Ocriticum]; Ocriticum is in Abruzzo (Italy) [SUPPORTED