    ('e911a780-13d9-401b-ae9d-4d1f5d4cc22b'::uuid, 'card_description', NULL, 'Near Hadda, the large monastery of Tapa Shotor yielded numerous sculptures in an archaeologically intact setting, and a stupa in its main courtyard, dug out by an all-Afghan team.', 'teaser-card-s021:e911a780-13d9-401b-ae9d-4d1f5d4cc22b:card_description', 'teaser-card-s021 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '42056cc932611ded521ee5938aad1c55bb3530048ff3766c30c07b2696d32350|cdbe25223c78840bbe449e6ab1fffd722b4c131051d149467d81b030c02938a1|cdbe25223c78840bbe449e6ab1fffd722b4c131051d149467d81b030c02938a1', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Hadda, the large monastery of Tapa Shotor yielded numerous sculptures in an archaeologically intact setting, and a stupa in its main courtyard, dug out by an all-Afghan team."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tapa Shotor is near Hadda [S1]; Tapa Shotor is a large monastery [S1]; it yielded numerous sculptures [S6]; the sculptures came from an archaeologically intact setting [S6]; a stupa was excavated in the main courtyard [S7]; the excavation was by an all-Afghan team [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tapa Shotor is a monastery (now an archaeological site) [SUPPORTED: https://en.wikipedia.org/wiki/Tapa_Shotor]; Tapa Shotor is near Hadda (Afghanistan) [SUPPORTED: https://en.wikipedia.org/wiki/Tapa_Shotor]; The monastery was large [SUPPORTED: https://en.wikipedia.org/wiki/Tapa_Shotor]; The monastery yielded numerous sculptures [SUPPORTED: 