    ('e9a63a95-86fb-4708-9041-0a7a74f2051d'::uuid, 'card_description', 'A fort from the 1st millennium BC, later adapted in the Roman period. The same strategic hilltop hosted a post-Medieval fair and a telegraph station centuries after that.', 'Built around 2,500 years ago, the Iron Age hillfort of Lambert''s Castle sits atop a Dorset hill rising to 256 metres, steep slopes on three sides, ramparts across the flat south.', 'teaser-card-s021:e9a63a95-86fb-4708-9041-0a7a74f2051d:card_description', 'teaser-card-s021 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'a9b59e5de730d22247eac60d108ea51f57ce67439a387d385511c11f1baa4bc3|b302479551f7495a56d86e23d2d5bff676fd8aa24cc6df46c07be5a26b7e7c7e|b302479551f7495a56d86e23d2d5bff676fd8aa24cc6df46c07be5a26b7e7c7e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Built around 2,500 years ago, the Iron Age hillfort of Lambert''s Castle sits atop a Dorset hill rising to 256 metres, steep slopes on three sides, ramparts across the flat south."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Lambert''s Castle was built around 2,500 years ago [S6]; it is an Iron Age hillfort [S1]; it is in Dorset [S1]; it sits at the summit of a hill [S4]; the hill rises to 256 metres [S4]; there are steep slopes on three sides of the fort [S5]; ramparts run across the flat southern approaches [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Lambert''s Castle is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Lambert%27s_Castle]; Lambert''s Castle is an Iron Age monument [SUPPORTED: https://en.wikipedia.org/wiki/Lambert%27s_Castle]; Lambert''s Castle is in Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Lambert%27s_Castle]; It was built around 2,500 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Lambert%27s_Castle]; The hill on which it sits rises to 256 metres [SUPPORTED: https://en.wikipedia.org/wiki/Lambert%27s_Castle]; The hillfort has steep slopes on three sides [SUPPORTED: https://en.wikipedia.org/wiki/Lambert%27s_Castle]; Ramparts run across the flat south of the hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Lambert%27s_Castle]"}]'::jsonb),
    ('ebadc068-2bac-468f-9b3c-df5c12bf446f'::uuid, 'card_description', 'An area rich in archaeology from the Early Bronze Age through the Iron Age, overlooking Cadbury Castle. Multiple eras of activity layer the landscape.', 'On a plateau overlooking Cadbury Castle, Sigwells gave up the earliest known bronze casting building in Britain, and mould fragments, some later refitted to a sword.', 'teaser-card-s021:ebadc068-2bac-468f-9b3c-df5c12bf446f:card_description', 'teaser-card-s021 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', '4ef4f540f254e1f53eeaa0b321cb6bca7b923d75473fce26d6ef91785e0ed290|5f187820185639460c78ac865ea824f43e867f3fe7dc01bc3ee1547d2687f5d2|5f187820185639460c78ac865ea824f43e867f3fe7dc01bc3ee1547d2687f5d2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a plateau overlooking Cadbury Castle, Sigwells gave up the earliest known bronze casting building in Britain, and mould fragments, some later refitted to a sword."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Sigwells is on a plateau [S1]; the plateau overlooks Cadbury Castle [S1]; the site gave up the earliest known bronze casting building in Britain [S2]; the site yielded mould fragments [S4]; some of the fragments were later refitted to a sword [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Sigwells is an archaeological site on a plateau (a rural plateau with a hamlet) in Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Sigwells]; Sigwells is on a plateau overlooking Cadbury Castle [SUPPORTED: https://en.wikipedia.org/wiki/Sigwells]; Sigwells gave up the earliest known bronze casting building in Britain [SUPPORTED: https://en.wikipedia.org/wiki/Sigwells]; Mould fragments were found at Sigwells [SUPPORTED: https://en.wikipedia.org/wiki/Sigwells]; Some of the mould fragments were later refitted to a sword [SUPPORTED: https://en.wikipedia.org/wiki/Sigwells]"}]'::jsonb),
    ('ebbad3eb-877c-4c7f-b6bf-66723f7b49e6'::uuid, 'card_description', 'Pottery similar to that found in Stentinello was found at Għar Dalam, but lacking details such as stamp decorations.', 'Bone deposits of dwarf elephant, hippopotamus, giant swan, deer and bear, of different ages, lie in Għar Dalam, where John H. Cooke dug in 1892 and pottery like Stentinello''s was found.', 'teaser-card-s021:ebbad3eb-877c-4c7f-b6bf-66723f7b49e6:card_description', 'teaser-card-s021 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'b72275b50d3468be5a4ec08de4f83d86d89b2d4c201c6295fa22c3acdc831671|b6deddae387ec76525d6dbcfa7ec4088eee39cc3ce82829bb3ca373119bc038a|b6deddae387ec76525d6dbcfa7ec4088eee39cc3ce82829bb3ca373119bc038a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Bone deposits of dwarf elephant, hippopotamus, giant swan, deer and bear, of different ages, lie in Għar Dalam, where John H. Cooke dug in 1892 and pottery like Stentinello''s was found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "bone deposits of dwarf elephant, hippopotamus, giant swan, deer and bear were found at Għar Dalam [S2]; the bone deposits are of different ages [S2]; John H. Cooke carried out an excavation there [S3]; the excavation was in 1892 [S3]; pottery similar to that found in Stentinello was found there [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Għar Dalam is a cave (a phreatic tube and cave) [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_Dalam]; Għar Dalam is in Malta, on the outskirts of Birżebbuġa [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_Dalam]; Bone deposits of dwarf elephant, hippopotamus, giant swan, deer and bear lie in Għar Dalam [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_Dalam]; The bone deposits are of different ages [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_Dalam]; John H. Cooke dug (excavated) at Għar Dalam in 1892 [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_Dalam]; Pottery like that of Stentinello was found at Għar Dalam [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_Dalam]"}]'::jsonb),
    ('ebf816e0-2353-4ed3-81bd-685d6480973f'::uuid, 'card_description', 'A Roman villa with original tiling and colored stucco, active from the Bronze Age through Late Antiquity. Punic and Roman tombs surround the complex.', 'On the highest point of a long, flat ridge, the Żejtun Roman Villa still shows original Roman tiling and coloured stucco, and evidence of a thriving olive oil industry.', 'teaser-card-s021:ebf816e0-2353-4ed3-81bd-685d6480973f:card_description', 'teaser-card-s021 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '75f3cd1e0825eccdfef402c4afdc3a3e7aff6053170d179c6b7d016e6a063571|f2b66c7a54e9d97416fe67a169032eb4f66393142a481be007fb6bf47655b685|f2b66c7a54e9d97416fe67a169032eb4f66393142a481be007fb6bf47655b685', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the highest point of a long, flat ridge, the Żejtun Roman Villa still shows original Roman tiling and coloured stucco, and evidence of a thriving olive oil industry."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the remains rest on the highest point of a ridge [S5]; the ridge is long and flat [S5]; the open-air remains show original Roman tiling [S2]; the open-air remains show coloured stucco [S2]; the excavation site gives evidence of a thriving olive oil industry [S4]; the site is a Roman villa [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Żejtun Roman Villa is a Roman villa (an archaeological site, a Roman rustic villa) at Żejtun [SUPPORTED: https://www.um.edu.mt/arts/classics-archaeo/ourresearch/zejtunromanvilla/]; The remains lie on the highest point of a long, flat ridge [SUPPORTED: https://en.wikipedia.org/wiki/%C5%BBejtun_Roman_villa]; The site still shows original Roman tiling [SUPPORTED: https://en.wikipedia.org/wiki/%C5%BBejtun_Roman_villa]; The site still shows coloured stucco (plastered walls decorated in colour) [SUPPORTED: https://www.um.edu.mt/arts/classics-archaeo/ourresearch/zejtunromanvilla/]; The site holds evidence of olive oil production (stone apparatus of an olive press) [SUPPORTED: https://www.um.edu.mt/arts/classics-archaeo/ourresearch/zejtunromanvilla/]; The evidence points to a thriving olive oil industry [SUPPORTED: https://en.wikipedia.org/wiki/%C5%BBejtun_Roman_villa]"}]'::jsonb),
    ('ece8c6c5-0934-4817-b30d-cc3c0e27899e'::uuid, 'card_description', 'Gurnard''s Head is a prominent headland on the north coast of the Penwith peninsula in Cornwall.', 'On Cornwall''s north coast, Gurnard''s Head bears pillow lavas formed by underwater eruptions up to 400 million years ago, and an Iron Age promontory fort, Trereen Dinas.', 'teaser-card-s021:ece8c6c5-0934-4817-b30d-cc3c0e27899e:card_description', 'teaser-card-s021 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', 'f41c5c9f2310cfcfae15c1a3d2a49ffff857b9ef406a9d32e556095cf5ae778e|bbdf7b49ca23af73660287b6cbfd111329cad5b737cde0735a26df8d937e3470|bbdf7b49ca23af73660287b6cbfd111329cad5b737cde0735a26df8d937e3470', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Cornwall''s north coast, Gurnard''s Head bears pillow lavas formed by underwater eruptions up to 400 million years ago, and an Iron Age promontory fort, Trereen Dinas."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Gurnard''s Head is on the north coast in Cornwall [S1]; it bears pillow lavas [S2]; the pillow lavas were formed by underwater eruptions [S2]; the eruptions were up to 400 million years ago [S2]; it bears an Iron Age promontory fort [S4]; the fort is called Trereen Dinas [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Gurnard''s Head is a headland (a promontory site) [SUPPORTED: https://en.wikipedia.org/wiki/Gurnard%27s_Head]; Gurnard''s Head lies on Cornwall''s north coast [SUPPORTED: https://www.cornwalls.co.uk/history/sites/gurnards_head.htm]; Gurnard''s Head bears pillow lavas (basaltic pillow lavas) [SUPPORTED: https://en.wikipedia.org/wiki/Gurnard%27s_Head]; The pillow lavas were formed by underwater eruptions [SUPPORTED: https://commons.wikimedia.org/wiki/File:Basaltic_Pillow_Lava_at_Gurnard%27s_Head_in_Cornwall.jpg]; The pillow lavas formed up to 400 million years ago [SUPPORTED: https://en.wikipedia.org/wiki/Gurnard%27s_Head]; Gurnard''s Head has a promontory fort [SUPPORTED: https://www.cornwalls.co.uk/history/sites/gurnards_head.htm]; The promontory fort is of the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Gurnard%27s_Head]; The fort is named Trereen Dinas [SUPPORTED: https://www.iwalkcornwall.co.uk/pi/trereen_dinas]"}]'::jsonb),
    ('ee6608f3-f192-4c43-ab41-1f7ad3c9507d'::uuid, 'card_description', 'Radiocarbon dating of the deposits has provided dates ranging from Romano-British to Early Medieval.', 'Some call it Fairy Cave: Dog Hole Cave near Storth is a shaft of 12 metres in Carboniferous Limestone, ending in a steep phreatic tube, where local scouts dug in the 1950s.', 'teaser-card-s021:ee6608f3-f192-4c43-ab41-1f7ad3c9507d:card_description', 'teaser-card-s021 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', 'd30d35e8af25c5aa0b14014dcd224da04c40497cc13adec1f58e8199b7d6fd68|7d83ada80dd73d59bcbf3323616321b6cd0e677597cbeafd9cf83f1040a2a742|7d83ada80dd73d59bcbf3323616321b6cd0e677597cbeafd9cf83f1040a2a742', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Some call it Fairy Cave: Dog Hole Cave near Storth is a shaft of 12 metres in Carboniferous Limestone, ending in a steep phreatic tube, where local scouts dug in the 1950s."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the cave is also called Fairy Cave [S2]; Dog Hole Cave is near Storth [S1]; the cave is a shaft 12 metres deep [S3]; the shaft is formed in Carboniferous Limestone [S3]; the shaft ends in a steeply dipping phreatic tube [S3]; local scouts excavated there in the 1950s [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dog Hole Cave is a cave near Storth (Cumbria, England) [SUPPORTED: https://en.wikipedia.org/wiki/Dog_Hole_Cave]; Some call it Fairy Cave [SUPPORTED: https://www.geograph.org.uk/photo/1681847]; The cave is a shaft of 12 metres [SUPPORTED: https://en.wikipedia.org/wiki/Dog_Hole_Cave]; The shaft is formed in Carboniferous Limestone [SUPPORTED: https://en.wikipedia.org/wiki/Dog_Hole_Cave]; The shaft ends in a steep phreatic tube [SUPPORTED: https://en.wikipedia.org/wiki/Dog_Hole_Cave]; Local scouts dug (excavated) the cave in the 1950s [SUPPORTED: https://en.wikipedia.org/wiki/Dog_Hole_Cave]"}]'::jsonb),
    ('eebdcbf3-42aa-4590-b07e-b3bbe40c309f'::uuid, 'card_description', 'While working a gravel quarry at Aymestrey, in June 1987, employees of ARC unearthed a hole with a stone lining, and human remains visible within.', 'In June 1987, quarry workers found a stone-lined pit: the Aymestrey Burial, a child in a foetal position with a bell beaker and a flint knife, from the Early Bronze Age.', 'teaser-card-s021:eebdcbf3-42aa-4590-b07e-b3bbe40c309f:card_description', 'teaser-card-s021 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '37f72b00e6d3e9f2a5916366ef5216056ec26c494301ff5c2feaaf21ce2af24e|fe158a6909d2005e239324df670692ec87d6ef6b431823e3399f19d990a42d9c|fe158a6909d2005e239324df670692ec87d6ef6b431823e3399f19d990a42d9c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In June 1987, quarry workers found a stone-lined pit: the Aymestrey Burial, a child in a foetal position with a bell beaker and a flint knife, from the Early Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the find was made in June 1987 [S2]; quarry workers found it [S2]; it was a stone-lined pit [S2, S3]; the site is the Aymestrey Burial [S1]; it held the body of a child [S3]; the child lay in a foetal position [S3]; a bell beaker lay alongside the body [S4]; a flint knife lay alongside the body [S4]; the burial dates to the Early Bronze Age [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Aymestrey Burial is a burial, a beaker cist (stone-lined grave), at Aymestrey [SUPPORTED: https://en.wikipedia.org/wiki/Aymestrey_burial]; It was found in June 1987 [SUPPORTED: https://en.wikipedia.org/wiki/Aymestrey_burial]; It was found by quarry workers [SUPPORTED: https://en.wikipedia.org/wiki/Aymestrey_burial]; It was a stone-lined pit [SUPPORTED: https://en.wikipedia.org/wiki/Aymestrey_burial]; The burial was of a child [SUPPORTED: https://app.leominstermuseum.org.uk/nfc5]; The child lay in a foetal position [SUPPORTED: https://en.wikipedia.org/wiki/Aymestrey_burial]; The burial held a bell beaker [SUPPORTED: https://en.wikipedia.org/wiki/Aymestrey_burial]; The burial held a flint knife [SUPPORTED: https://app.leominstermuseum.org.uk/nfc5]; The burial dates from the Early Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Aymestrey_burial]"}]'::jsonb),
    ('ef7d92df-a76b-4c2c-8160-32ad83100a71'::uuid, 'card_description', 'Stones on Knockmany Hill''s summit are carved with spirals and concentric circles — rare megalithic art in a monument dated to 3000 BC. A concrete shelter built in 1959 now protects the carved slabs.', 'On the summit of Knockmany Hill, the Knockmany Passage Tomb was built around 3000 BC. Of its 13 sandstone orthostats, three bear carved concentric circles, spirals and zigzags.', 'teaser-card-s021:ef7d92df-a76b-4c2c-8160-32ad83100a71:card_description', 'teaser-card-s021 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '5fbfe625c69131c39aa82a0f1910640da9ba8c8bc83b7e150538b80d8377c6b1|32239f86c7e45a92dec7797fad04413dcf2b2ad3216b3bd4a990573c561ca6d2|32239f86c7e45a92dec7797fad04413dcf2b2ad3216b3bd4a990573c561ca6d2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the summit of Knockmany Hill, the Knockmany Passage Tomb was built around 3000 BC. Of its 13 sandstone orthostats, three bear carved concentric circles, spirals and zigzags."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the tomb stands on the summit of Knockmany Hill [S1]; the tomb was built around 3000 BC [S3]; 13 sandstone orthostats remain [S5]; three of the orthostats bear carved decorations [S5]; the carvings include concentric circles, spirals and zigzags [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Knockmany Passage Tomb is a passage tomb (burial monument) on the summit of Knockmany Hill in Northern Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Knockmany_Passage_Tomb]; The tomb was built around 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Knockmany_Passage_Tomb]; The tomb has 13 orthostats [SUPPORTED: https://en.wikipedia.org/wiki/Knockmany_Passage_Tomb]; The orthostats are of sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Knockmany_Passage_Tomb]; Three of the orthostats bear carved decoration [SUPPORTED: https://en.wikipedia.org/wiki/Knockmany_Passage_Tomb]; The carvings include concentric circles, spirals and zigzags [SUPPORTED: https://en.wikipedia.org/wiki/Knockmany_Passage_Tomb]"}]'::jsonb),
    ('f10115c4-5ca9-4d69-990c-8054f9962ea3'::uuid, 'card_description', 'A cluster of small catacombs from 500–1000 AD. Though modest compared to larger sites, they reveal a substantial early Christian community.', 'The Salina Catacombs open on to a low ridge facing a now lost Roman harbour. Their most impressive hypogeum is adorned with two decorated pillars, an agape table and two baldacchino tombs.', 'teaser-card-s021:f10115c4-5ca9-4d69-990c-8054f9962ea3:card_description', 'teaser-card-s021 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '55a62d00ff9bac8df47ba9a6d803b7a2326da6eaadf9c774c879c992c919e35f|c215cfce7f5b53327a59789f970a2181cc951437c224c750d98be9ccc6a12714|c215cfce7f5b53327a59789f970a2181cc951437c224c750d98be9ccc6a12714', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Salina Catacombs open on to a low ridge facing a now lost Roman harbour. Their most impressive hypogeum is adorned with two decorated pillars, an agape table and two baldacchino tombs."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the catacombs open on to a low ridge [S3]; the ridge faces a Roman harbour [S3]; the harbour is now lost [S3]; the site has hypogea, one of which is the most impressive [S4, S5]; the most impressive hypogeum is adorned with two decorated pillars [S5]; the most impressive hypogeum is adorned with an agape table [S5]; the most impressive hypogeum is adorned with two baldacchino tombs [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Salina Catacombs are a cluster of catacombs (an ancient burial site) in Malta [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]; The catacombs open on to a low ridge [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]; The ridge faces a harbour [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]; The harbour was Roman [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]; The Roman harbour is now lost [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]; The site has a hypogeum that is the most impressive of its hypogea [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]; The most impressive hypogeum is adorned with two decorated pillars [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]; The most impressive hypogeum has an agape table [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]; The most impressive hypogeum has two baldacchino tombs [SUPPORTED: https://en.wikipedia.org/wiki/Salina_Catacombs]"}]'::jsonb),
    ('f1710818-b1bc-401e-95ca-cae1bb55ada8'::uuid, 'card_description', 'Occupied from the 7th to 4th millennia BC, this Neolithic settlement of round stone houses became a UNESCO World Heritage Site in 1998. Burials were placed beneath the house floors.', 'On a hillside in the Maroni valley, Khirokitia, whose name may mean Pig-cradle, was home to Neolithic farmers of wheat, barley and lentils who herded sheep, goats and pigs.', 'teaser-card-s021:f1710818-b1bc-401e-95ca-cae1bb55ada8:card_description', 'teaser-card-s021 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', 'fd8bc67b7906e3306eb138611ad9caa696cedad535bb454860dafd7543c43731|f5a7597c5492d5d2b161b3b973cde2b8a4cab87c25fdf8a7eab2d65914c4e192|f5a7597c5492d5d2b161b3b973cde2b8a4cab87c25fdf8a7eab2d65914c4e192', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a hillside in the Maroni valley, Khirokitia, whose name may mean Pig-cradle, was home to Neolithic farmers of wheat, barley and lentils who herded sheep, goats and pigs."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the settlement lay on a hillside in the valley of the Maroni [S5]; the name may mean Pig-cradle [S1]; Khirokitia was home to Neolithic inhabitants [S1, S6]; they farmed wheat, barley and lentils [S6]; they herded sheep, goats and pigs [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Khirokitia is a Neolithic archaeological site (settlement) in Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Khirokitia]; Khirokitia was a settlement on a hillside in the Maroni valley [SUPPORTED: https://en.wikipedia.org/wiki/Khirokitia]; The name Khirokitia may mean Pig-cradle [SUPPORTED: https://en.wikipedia.org/wiki/Khirokitia]; Its Neolithic inhabitants were farmers who grew wheat, barley and lentils [SUPPORTED: https://en.wikipedia.org/wiki/Khirokitia]; Its inhabitants herded sheep, goats and pigs [SUPPORTED: https://en.wikipedia.org/wiki/Khirokitia]"}]'::jsonb),
    ('f28a2d38-f5a9-49f2-83c8-53bb4c61cae4'::uuid, 'card_description', 'A Roman castellum built in 4–5 AD where the Vecht branched off from the Rhine. It guarded the waterway leading to Lake Flevo, precursor of the Zuiderzee.', 'Where the Vecht branched from the Rhine, Tiberius had the fort of Fectio built in 4 or 5 AD. Caligula visited in 40 AD; around 70 AD, at the time of the Batava revolt, it burned completely.', 'teaser-card-s021:f28a2d38-f5a9-49f2-83c8-53bb4c61cae4:card_description', 'teaser-card-s021 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '5ebc575ff4d42deaa855269ea360d03ce41d5aa69adeca1dab9761f914eba80b|dc2c62092e9ef188f2edef9e6464af94709142d67ade08cd2d0ad8997f4666ce|dc2c62092e9ef188f2edef9e6464af94709142d67ade08cd2d0ad8997f4666ce', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Where the Vecht branched from the Rhine, Tiberius had the fort of Fectio built in 4 or 5 AD. Caligula visited in 40 AD; around 70 AD, at the time of the Batava revolt, it burned completely."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Fectio lay where the Vecht branched from the Rhine [S2]; Fectio was a fort [S1, S8]; Tiberius had the fort built [S4]; it was built in 4 or 5 AD [S1, S4]; Caligula visited Fectio [S5]; the visit was in 40 AD [S5]; around 70 AD the fort burned completely [S7]; the burning came at the time of the Batava revolt [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Fectio was a Roman fort (castellum) in what is now the Netherlands [SUPPORTED: https://en.wikipedia.org/wiki/Fectio]; Fectio lay in the Netherlands (near Vechten, Bunnik, Utrecht) [SUPPORTED: https://en.wikipedia.org/wiki/Fectio]; It stood where the Vecht branched from the Rhine [SUPPORTED: https://en.wikipedia.org/wiki/Fectio]; The fort was built by order of Tiberius [SUPPORTED: https://en.wikipedia.org/wiki/Fectio]; The fort was built in 4 or 5 AD [SUPPORTED: https://en.wikipedia.org/wiki/Fectio]; Caligula visited Fectio in 40 AD [SUPPORTED: https://en.wikipedia.org/wiki/Fectio]; Around 70 AD, at the time of the Batavian revolt, the fort was burned [SUPPORTED: https://en.wikipedia.org/wiki/Fectio]; The fort burned completely [SUPPORTED: https://en.wikipedia.org/wiki/Fectio]"}]'::jsonb),
    ('f292ac8c-041c-4740-906c-af202af10489'::uuid, 'card_description', 'Seat of the ancient D''mt kingdom, with stelae up to 14 metres tall inscribed in Ge''ez script. Dating from around 500 BC, it predates the Aksumite empire.', 'Keskese, 8 kilometres north of Matara, dates from around 500 BCE and is renowned for its ancient steles, some of its inscribed edifices rising up to 14 metres in height.', 'teaser-card-s021:f292ac8c-041c-4740-906c-af202af10489:card_description', 'teaser-card-s021 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', 'c31c876de881ad286db6e6977cfb61317ca9a3f00176cebc4bbcffc53a67efcc|e8890ffd168a364db85d603c76c4fa5e322d7e2f21b8f68ec4a8164c630268ce|e8890ffd168a364db85d603c76c4fa5e322d7e2f21b8f68ec4a8164c630268ce', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Keskese, 8 kilometres north of Matara, dates from around 500 BCE and is renowned for its ancient steles, some of its inscribed edifices rising up to 14 metres in height."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Keskese is 8 kilometres north of Matara [S2]; it dates from around 500 BCE [S3]; it is renowned for its ancient steles [S3]; some of the edifices at the site are inscribed [S4]; some of the edifices rise up to 14 metres in height [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Keskese is an archaeological site (ancient ruin) in Eritrea [SUPPORTED: https://en.wikipedia.org/wiki/Keskese]; Keskese is situated 8 kilometres north of Matara [SUPPORTED: https://en.wikipedia.org/wiki/Keskese]; Keskese dates from around 500 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Keskese]; Keskese is renowned for its ancient steles [SUPPORTED: https://en.wikipedia.org/wiki/Keskese]; Some of the edifices at the site are inscribed [SUPPORTED: https://en.wikipedia.org/wiki/Keskese]; Some of the inscribed edifices at the site rise up to 14 metres in height [SUPPORTED: https://en.wikipedia.org/wiki/Keskese]"}]'::jsonb),
    ('f309bc3f-15a8-4f5d-afbb-7d2128b9c1f7'::uuid, 'card_description', 'Founded in the 3rd century BC, this oppidum reached 380 hectares at its peak in the late 2nd century BC, housing up to 10,000 people. A 7.2 km wall enclosed a settlement of urban scale.', 'Baltic amber, Mediterranean wine amphorae, glass beads and bracelets made on site: the Oppidum of Manching was a Celtic town that grew to 380 hectares in the late La Tène period.', 'teaser-card-s021:f309bc3f-15a8-4f5d-afbb-7d2128b9c1f7:card_description', 'teaser-card-s021 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'aa66092f17935da393e3ab7abfcc8acac99970a389e218fe6acf85fe813ace48|80408662d1b58129ce5a57a41a82296e932983e09254531cdecab7649867f54f|80408662d1b58129ce5a57a41a82296e932983e09254531cdecab7649867f54f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Baltic amber, Mediterranean wine amphorae, glass beads and bracelets made on site: the Oppidum of Manching was a Celtic town that grew to 380 hectares in the late La Tène period."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Baltic amber was found at the site [S6]; Mediterranean wine amphorae were found at the site [S6]; glass beads and bracelets were made on site [S5]; the Oppidum of Manching was a Celtic town [S1, S2]; it grew to 380 hectares [S3]; it reached that size in the late La Tène period [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Oppidum of Manching was a town (a city-like settlement, at Manching near Ingolstadt in Bavaria, Germany) [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_of_Manching]; The town was Celtic [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_of_Manching]; It grew to 380 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_of_Manching]; It reached that size in the late La Tène period [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_of_Manching]; Baltic amber was found at Manching [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_of_Manching]; Mediterranean wine amphorae were found at Manching [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_of_Manching]; Glass beads and bracelets were made on site at Manching [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_of_Manching]"}]'::jsonb),
    ('f32a3584-270b-43a7-9c12-859bb6214b11'::uuid, 'card_description', 'A megalithic complex with a wedge tomb, two stone circles, and paired stone alignments all clustered together. A single fallen slab hints at a once-larger monument.', 'In the Keel River valley, high on Musherabeg mountain, Glantane East gathers a wedge tomb, two stone circles and a pair of stone alignments. One slab of the larger circle has fallen.', 'teaser-card-s021:f32a3584-270b-43a7-9c12-859bb6214b11:card_description', 'teaser-card-s021 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '3279ed505ff5ccf6ec0e18985cd21936abcbe0613863837e2425abcffde9fe5e|127e440934dcf62abb9db453d55efcc7cfd145718f773285a57618db09105afc|127e440934dcf62abb9db453d55efcc7cfd145718f773285a57618db09105afc', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Keel River valley, high on Musherabeg mountain, Glantane East gathers a wedge tomb, two stone circles and a pair of stone alignments. One slab of the larger circle has fallen."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies in the Keel River valley [S2]; it lies high on Musherabeg mountain [S2]; the complex includes a wedge tomb [S3]; the complex includes two stone circles [S3]; the complex includes a pair of stone alignments [S3]; one slab of the larger stone circle has fallen [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Glantane East is a megalithic complex (a group of prehistoric monuments) in Ireland, County Cork [SUPPORTED: https://en.wikipedia.org/wiki/Glantane_East]; It lies in the Keel River valley [SUPPORTED: https://en.wikipedia.org/wiki/Glantane_East]; It lies high on Musherabeg mountain (upper slopes) [SUPPORTED: https://en.wikipedia.org/wiki/Glantane_East]; The complex includes a wedge tomb [SUPPORTED: https://en.wikipedia.org/wiki/Glantane_East]; The complex includes two stone circles [SUPPORTED: https://en.wikipedia.org/wiki/Glantane_East]; The complex includes a pair of stone alignments [SUPPORTED: https://en.wikipedia.org/wiki/Glantane_East]; One slab of the larger circle has fallen [SUPPORTED: https://en.wikipedia.org/wiki/Glantane_East]"}]'::jsonb),
    ('f3c2a268-f63e-41be-b587-1885a7e1cfae'::uuid, 'card_description', 'Island in Lake Malaren housing Birka, a Viking-age trading town active 750-975 AD declared a World Heritage Site in 1993. The oldest relic on the island predates the Viking settlement.', 'On Björkö, the oldest remains are a burial ground on the elevated south. A shrine of nine stone structures, one a cairn called Ingas grav, points to Bronze Age seasonal hunters and fishers.', 'teaser-card-s021:f3c2a268-f63e-41be-b587-1885a7e1cfae:card_description', 'teaser-card-s021 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '8eb9197bd4946be99c7b7591a747b1af2a96409a8c0f839e5a763d49f8a37f43|0b17e219aee4826aa7eb14e19d9be0c0d8d12cdc4751caf9269ee396a05e80c5|0b17e219aee4826aa7eb14e19d9be0c0d8d12cdc4751caf9269ee396a05e80c5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Björkö, the oldest remains are a burial ground on the elevated south. A shrine of nine stone structures, one a cairn called Ingas grav, points to Bronze Age seasonal hunters and fishers."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the oldest remains on Björkö are a burial ground [S2]; the burial ground lies on the elevated south of the island [S2]; there is a shrine of nine stone structures [S3]; one of the structures is a cairn called Ingas grav [S3]; the structures indicate a Bronze Age settlement [S4]; the people of that settlement were seasonal hunters and fishers who visited the island [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Björkö is an island (in Ekerö Municipality, Sweden) with ancient remains [SUPPORTED: https://en.wikipedia.org/wiki/Bj%C3%B6rk%C3%B6_(Eker%C3%B6)]; The oldest remains on Björkö are a burial ground [SUPPORTED: https://en.wikipedia.org/wiki/Bj%C3%B6rk%C3%B6_(Eker%C3%B6)]; The burial ground lies on the elevated south of the island [SUPPORTED: https://en.wikipedia.org/wiki/Bj%C3%B6rk%C3%B6_(Eker%C3%B6)]; A shrine comprises nine stone structures [SUPPORTED: https://en.wikipedia.org/wiki/Bj%C3%B6rk%C3%B6_(Eker%C3%B6)]; One of the structures is a cairn called Ingas grav [SUPPORTED: https://en.wikipedia.org/wiki/Bj%C3%B6rk%C3%B6_(Eker%C3%B6)]; The shrine points to Bronze Age people who came seasonally to hunt and fish [SUPPORTED: https://en.wikipedia.org/wiki/Bj%C3%B6rk%C3%B6_(Eker%C3%B6)]"}]'::jsonb),
    ('f4388f7e-a59e-45a0-bf56-44a5f75a4ff5'::uuid, 'card_description', 'A Bronze Age site with tombs and a reconstructed 12-metre tower tomb from the Umm al-Nar culture. 3,000-year-old fingerprints survive on a wall.', 'The reconstructed Grand Tomb, a tower 12 m in diameter, rises at Hili Archaeological park in Al Ain, the largest Bronze Age site in the UAE, among tombs of the Umm al-Nar culture.', 'teaser-card-s021:f4388f7e-a59e-45a0-bf56-44a5f75a4ff5:card_description', 'teaser-card-s021 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '001739c41185d464a378af4592c70686bbb7bcde3a6f0ca462bab2fa6e30739f|8eef2383b42c5fe42403649e888da056e11c80f3583ceb81a97308f55390eb50|8eef2383b42c5fe42403649e888da056e11c80f3583ceb81a97308f55390eb50', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The reconstructed Grand Tomb, a tower 12 m in diameter, rises at Hili Archaeological park in Al Ain, the largest Bronze Age site in the UAE, among tombs of the Umm al-Nar culture."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Grand Tomb has been reconstructed [S4]; the Grand Tomb is a tower 12 m in diameter [S4]; it stands at Hili Archaeological Park [S1, S4]; the park is in Al Ain [S1]; Hili is the largest Bronze Age site in the UAE [S2]; the tombs there belong to the Umm al-Nar culture [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hili Archaeological Park in Al Ain (United Arab Emirates) is the location of a Bronze Age site [SUPPORTED: https://en.wikipedia.org/wiki/Hili_Archaeological_Park]; Hili is the largest Bronze Age site in the UAE [SUPPORTED: https://en.wikipedia.org/wiki/Hili_Archaeological_Park]; The Grand Tomb at Hili is a tower [SUPPORTED: https://en.wikipedia.org/wiki/Hili_Archaeological_Park]; The tower is 12 m in diameter [SUPPORTED: https://abudhabiculture.ae/en/Cultural-Heritage/Tangible/UNESCO-World-Heritage-Site/Hili-Sites]; The Grand Tomb has been reconstructed [SUPPORTED: https://en.wikipedia.org/wiki/Hili_Archaeological_Park]; The Grand Tomb stands in the Hili Archaeological Park [SUPPORTED: https://abudhabiculture.ae/en/Cultural-Heritage/Tangible/UNESCO-World-Heritage-Site/Hili-Sites]; The tombs at Hili belong to the Umm al-Nar culture [SUPPORTED: https://en.wikipedia.org/wiki/Hili_Archaeological_Park]"}]'::jsonb),
    ('f4955fe7-d4e9-4de7-9812-0fc7e94c0620'::uuid, 'card_description', 'The obelisk''s creators began to carve it directly out of bedrock, but cracks appeared in the granite and the project was abandoned.', 'The largest known ancient obelisk still lies bound to the bedrock at Aswan: the Unfinished Obelisk, abandoned when its granite cracked, its workers'' tool marks still clearly visible.', 'teaser-card-s021:f4955fe7-d4e9-4de7-9812-0fc7e94c0620:card_description', 'teaser-card-s021 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '0babbfc0454b9a7a3c336067408b6274f2594ca928893cffbced0a9f8549e269|65c129a9768acef7228f5988cea163d21b4db55eb8ea549d40dd1b1a811529ee|65c129a9768acef7228f5988cea163d21b4db55eb8ea549d40dd1b1a811529ee', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The largest known ancient obelisk still lies bound to the bedrock at Aswan: the Unfinished Obelisk, abandoned when its granite cracked, its workers'' tool marks still clearly visible."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "it is the largest known ancient obelisk [S1]; it is still attached to the bedrock [S6]; it is at Aswan [S1]; it was abandoned when the granite cracked [S5]; the workers'' tool marks are still clearly visible [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Unfinished Obelisk is an ancient obelisk left in the stone quarries at Aswan, Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Unfinished_obelisk]; It is the largest known ancient obelisk [SUPPORTED: https://en.wikipedia.org/wiki/Unfinished_obelisk]; It still lies bound to (attached to) the bedrock [SUPPORTED: https://en.wikipedia.org/wiki/Unfinished_obelisk]; It was abandoned when its granite cracked [SUPPORTED: https://en.wikipedia.org/wiki/Unfinished_obelisk]; The obelisk is of granite [SUPPORTED: https://en.wikipedia.org/wiki/Unfinished_obelisk]; The workers'' tool marks are still clearly visible [SUPPORTED: https://en.wikipedia.org/wiki/Unfinished_obelisk]"}]'::jsonb),
    ('f4f03f57-9987-48a4-98c0-c165e8e907fe'::uuid, 'card_description', 'Capital of Lesbos since the 11th century BC, once home to the poet Sappho. Its ancient dual harbors were linked by a 700-metre channel cut through the narrow isthmus between them.', 'In ancient Mytilene, a channel 700 m long and 30 m wide linked the early harbors, and the Roman writer Longus speaks of white stone bridges linking the two sides.', 'teaser-card-s021:f4f03f57-9987-48a4-98c0-c165e8e907fe:card_description', 'teaser-card-s021 (teaser-card): teaser card, 162 characters, checked PASS, web-verified VERIFIED', 'f2ef784e731f57c2ebff0fdd93d7d759fc02ab4b7ec0c67c758fc502ca3c7ca5|d85a98301b5da6179b93f3901cc37e1545143f4d0945f9634e77f57ed8c31852|d85a98301b5da6179b93f3901cc37e1545143f4d0945f9634e77f57ed8c31852', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In ancient Mytilene, a channel 700 m long and 30 m wide linked the early harbors, and the Roman writer Longus speaks of white stone bridges linking the two sides."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mytilene is an ancient city [S1]; a channel linked the early harbors [S2]; the channel was 700 m long [S2]; the channel was 30 m wide [S2]; the Roman writer Longus speaks of bridges [S3]; the bridges are of white stone [S3]; the bridges link the two sides [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-011 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mytilene is an ancient city (and port) in Greece, on the island of Lesbos [SUPPORTED: https://en.wikipedia.org/wiki/Mytilene]; Ancient Mytilene was a city with early harbors (a north and a south harbor) [SUPPORTED: https://en.wikipedia.org/wiki/Mytilene]; In ancient times a channel linked the early harbors of Mytilene [SUPPORTED: https://en.wikipedia.org/wiki/Mytilene]; The channel was 700 m long [SUPPORTED: https://en.wikipedia.org/wiki/Mytilene]; The channel was 30 m wide [SUPPORTED: https://en.wikipedia.org/wiki/Mytilene]; Longus was a writer of the Roman era (2nd century AD), author of Daphnis and Chloe [SUPPORTED: https://en.wikipedia.org/wiki/Longus]; Longus writes of Mytilene''s bridges (Daphnis and Chloe describes Mytilene as adorned with bridges) [SUPPORTED: https://www.gutenberg.org/ebooks/55406.txt.utf-8]; The bridges Longus mentions are of white stone [SUPPORTED: https://www.gutenberg.org/ebooks/55406.txt.utf-8]; The bridges linked the two sides of the channel [SUPPORTED: https://en.wikipedia.org/wiki/Mytilene]"}]'::jsonb),
    ('f54065ac-566a-476e-9261-76c541fdc0b6'::uuid, 'card_description', 'The site was first explored in 1928 when Romano-British tile and pot and tesserae were found.', 'By the River Riccal lies Beadlam Roman Villa, a large Romano-British farm of the third and fourth centuries AD, with a mosaic pavement and buildings on three sides of a courtyard.', 'teaser-card-s021:f54065ac-566a-476e-9261-76c541fdc0b6:card_description', 'teaser-card-s021 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '28e7c44da2572fef7c36bf63917c05700aebb3c34dd781e6d07edfd2826ff62c|380d500f0ad44a648af4134a1395640db22b747637abf17259d2bd6e8c17516e|380d500f0ad44a648af4134a1395640db22b747637abf17259d2bd6e8c17516e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "By the River Riccal lies Beadlam Roman Villa, a large Romano-British farm of the third and fourth centuries AD, with a mosaic pavement and buildings on three sides of a courtyard."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the villa lies by the River Riccal [S1]; it is a large Romano-British farm [S3]; it dates to the third and fourth centuries AD [S3]; a mosaic pavement was found there [S5]; buildings form three sides of a courtyard [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Beadlam Roman Villa is a Roman villa, a large Romano-British farm, in North Yorkshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Beadlam_Roman_villa]; It lies by the River Riccal [SUPPORTED: https://en.wikipedia.org/wiki/Beadlam_Roman_villa]; The farm dates to the third and fourth centuries AD [SUPPORTED: https://en.wikipedia.org/wiki/Beadlam_Roman_villa]; The site has a mosaic pavement [SUPPORTED: https://en.wikipedia.org/wiki/Beadlam_Roman_villa]; It has buildings on three sides of a courtyard [SUPPORTED: https://en.wikipedia.org/wiki/Beadlam_Roman_villa]"}]'::jsonb),
    ('f56eb08e-29e1-42dc-b238-4867b12ba88b'::uuid, 'card_description', 'Peyre-Brune is a Neolithic dolmen situated near Saint-Aquilin in the department of the Dordogne.', 'Surrounded by woods on a rise near Saint-Aquilin in the Dordogne, Peyre-Brune is a Neolithic dolmen: one rectangular chamber, the burial tomb of a local chieftain who was not incinerated.', 'teaser-card-s021:f56eb08e-29e1-42dc-b238-4867b12ba88b:card_description', 'teaser-card-s021 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'f9f7a4ee2bef2a82eef2a3319c9c6820e4a7ebdbdf2fafc066dabe883db69cd9|83c2aa5a441acc10bf69df1094aba8e0e676807413ba5fb820752781f37db96b|83c2aa5a441acc10bf69df1094aba8e0e676807413ba5fb820752781f37db96b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Surrounded by woods on a rise near Saint-Aquilin in the Dordogne, Peyre-Brune is a Neolithic dolmen: one rectangular chamber, the burial tomb of a local chieftain who was not incinerated."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the dolmen is surrounded by woods [S3]; it stands on a rise [S3]; it is near Saint-Aquilin in the Dordogne [S1]; Peyre-Brune is a Neolithic dolmen [S1]; it has one rectangular chamber [S4]; it was the burial tomb of a local chieftain [S5]; the person buried was not incinerated [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Peyre-Brune is a dolmen (a megalithic tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; The dolmen is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; It is near Saint-Aquilin [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; It is in the Dordogne (France) [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; It is surrounded by woods [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; It stands on a rise (a topographic high) [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; It has a single chamber [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; The chamber is rectangular [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; It was a burial tomb [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; The person buried was a local chieftain [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]; The person buried was not incinerated [SUPPORTED: https://en.wikipedia.org/wiki/Peyre-Brune]"}]'::jsonb),
    ('f70384d7-00ec-45ba-b086-bf1aba816f84'::uuid, 'card_description', 'A post-Minoan city near Neapoli that flourished in the 8th–6th century BC. Its stone walls bear the oldest known inscribed legal code — predating all classical-era law codes.', 'Near Neapoli on Crete lies Dreros, a post-Minoan site that declined so far in Hellenistic times it was not among the thirty Cretan cities that signed a pact with Eumenes II in 183 BCE.', 'teaser-card-s021:f70384d7-00ec-45ba-b086-bf1aba816f84:card_description', 'teaser-card-s021 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '9437ac7845648cdc3f9ecc579dfa98852131130324ce3c08b37a2cfbbed4b0a3|1d783bd8ad707e9be4dd03d1650594a084137494d11c07e126d54b6c271e1641|1d783bd8ad707e9be4dd03d1650594a084137494d11c07e126d54b6c271e1641', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Neapoli on Crete lies Dreros, a post-Minoan site that declined so far in Hellenistic times it was not among the thirty Cretan cities that signed a pact with Eumenes II in 183 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dreros lies near Neapoli [S1]; it is on Crete [S1]; it is a post-Minoan site [S1]; it declined in importance in Hellenistic times [S2]; it was not among the thirty Cretan cities that signed a pact [S2]; the pact was with Eumenes II [S2]; the pact was signed in 183 BCE [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Dreros is an archaeological site (a post-Minoan settlement/city) [SUPPORTED: https://en.wikipedia.org/wiki/Dreros]; Dreros is post-Minoan [SUPPORTED: https://en.wikipedia.org/wiki/Dreros]; Dreros lies near Neapoli [SUPPORTED: https://en.wikipedia.org/wiki/Dreros]; Dreros is on Crete [SUPPORTED: https://en.wikipedia.org/wiki/Dreros]; Dreros declined in importance in Hellenistic times [SUPPORTED: https://en.wikipedia.org/wiki/Dreros]; Dreros was not among the thirty Cretan cities that signed a pact [SUPPORTED: https://en.wikipedia.org/wiki/Dreros]; The pact was made with Eumenes II [SUPPORTED: https://en.wikipedia.org/wiki/Dreros]; The pact was signed in 183 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Dreros]"}]'::jsonb),
    ('f7847cdc-5030-4ccf-bcdc-df1a6e47fce3'::uuid, 'card_description', 'The enclosure is the original example of a type of prehistoric feature, the "Martin Down style enclosure": they are small enclosures of the Bronze Age, area often less than 0.3 hectares.', 'A single bank and an external ditch frame the Martin Down Enclosure in Hampshire, the original example of the small Bronze Age enclosures considered to be domestic settlements.', 'teaser-card-s021:f7847cdc-5030-4ccf-bcdc-df1a6e47fce3:card_description', 'teaser-card-s021 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'af9d6aa974704bc6407653394b88e611b82f9eabe7ae3a96d75a0e1cf18a9370|62a45ea8913a0f7dbb3fb0129b3e1d4441bf5bde043d5b3902fe6e4909306bb3|62a45ea8913a0f7dbb3fb0129b3e1d4441bf5bde043d5b3902fe6e4909306bb3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A single bank and an external ditch frame the Martin Down Enclosure in Hampshire, the original example of the small Bronze Age enclosures considered to be domestic settlements."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the enclosure has a single bank [S6]; it has an external ditch [S6]; it is in Hampshire [S1]; it is the original example of the Martin Down style enclosure [S4]; such enclosures are small and of the Bronze Age [S4]; such enclosures are considered to be domestic settlements [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Martin Down Enclosure is an archaeological site, an enclosure (a Bronze Age enclosure considered a domestic settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Martin_Down_Enclosure]; It is in Hampshire [SUPPORTED: https://en.wikipedia.org/wiki/Martin_Down_Enclosure]; It has a single bank [SUPPORTED: https://en.wikipedia.org/wiki/Martin_Down_Enclosure]; It has an external ditch [SUPPORTED: https://en.wikipedia.org/wiki/Martin_Down_Enclosure]; It is the original example of the type of small enclosures [SUPPORTED: https://en.wikipedia.org/wiki/Martin_Down_Enclosure]; The type consists of small enclosures [SUPPORTED: https://en.wikipedia.org/wiki/Martin_Down_Enclosure]; The type dates to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Martin_Down_Enclosure]; These enclosures are considered to be domestic settlements [SUPPORTED: https://en.wikipedia.org/wiki/Martin_Down_Enclosure]"}]'::jsonb),
    ('f96b9c6e-f51d-4cb7-88b2-3015b25bd05c'::uuid, 'card_description', 'The first Bronze Age site found in the country, with burials containing pottery filled with animal bones, beads, and spear points. No iron was found, helping date the site precisely.', 'In the Bronze Age cemetery of Nyaung-gan, 43 individuals were found, most buried with the head pointing north. It was the first site in Myanmar to have artefacts dating to the Bronze Age.', 'teaser-card-s021:f96b9c6e-f51d-4cb7-88b2-3015b25bd05c:card_description', 'teaser-card-s021 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'c4749873d8f62ce58d430571a0d254ff178f0a9d86c379e0a54e69d34dbe4f42|8df9d49b07149855b50041fb8444b3773b4aae427bee8f07e3f439d4b958a124|8df9d49b07149855b50041fb8444b3773b4aae427bee8f07e3f439d4b958a124', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Bronze Age cemetery of Nyaung-gan, 43 individuals were found, most buried with the head pointing north. It was the first site in Myanmar to have artefacts dating to the Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Nyaung-gan is a Bronze Age cemetery [S1]; 43 individuals were found [S5]; most were buried with the head pointing north [S4]; it was the first site in Myanmar to have artefacts dating to the Bronze Age [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Nyaung-gan is a Bronze Age cemetery (in Myanmar) [SUPPORTED: https://en.wikipedia.org/wiki/Nyaung-gan]; 43 individuals were found at the cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Nyaung-gan]; Most of the burials were buried with the head pointing north [SUPPORTED: https://en.wikipedia.org/wiki/Nyaung-gan]; It was the first site in Myanmar to have artefacts dating to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Nyaung-gan]"}]'::jsonb),
    ('fa2037ed-54b7-425a-9650-27f0e25ac274'::uuid, 'card_description', 'A Neolithic stone avenue curving southwest from Avebury, now vanished except for a single stone called Adam. Excavations revealed parallel rows of buried stone sockets.', 'The Beckhampton Avenue curved from Avebury towards The Longstones, yet only one stone, called Adam, still stands. Excavations in 2000 revealed the parallel rows of holes that held them.', 'teaser-card-s021:fa2037ed-54b7-425a-9650-27f0e25ac274:card_description', 'teaser-card-s021 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'ef2dcf6462aee78492548a584c4db3346e4c444e22b64473c82aef723ab83ef4|9cf84b4c8d3c4473f1400c75fa3dfb159ea180d33c37bac2534b7a6269156271|9cf84b4c8d3c4473f1400c75fa3dfb159ea180d33c37bac2534b7a6269156271', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Beckhampton Avenue curved from Avebury towards The Longstones, yet only one stone, called Adam, still stands. Excavations in 2000 revealed the parallel rows of holes that held them."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the avenue was curving [S1]; the avenue ran from Avebury towards The Longstones [S1]; only one stone of the avenue still stands [S3]; the standing stone is called Adam [S3]; excavations took place in 2000 [S5]; the excavations revealed parallel rows of holes [S5]; the holes held the avenue''s stones [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Beckhampton Avenue is a prehistoric avenue of stones [SUPPORTED: https://en.wikipedia.org/wiki/Beckhampton_Avenue]; The avenue was curved [SUPPORTED: https://en.wikipedia.org/wiki/Beckhampton_Avenue]; The avenue ran from Avebury [SUPPORTED: https://en.wikipedia.org/wiki/Beckhampton_Avenue]; The avenue ran towards The Longstones [SUPPORTED: https://en.wikipedia.org/wiki/Beckhampton_Avenue]; Only one stone of the avenue still stands [SUPPORTED: https://en.wikipedia.org/wiki/Beckhampton_Avenue]; The one standing stone is called Adam [SUPPORTED: https://en.wikipedia.org/wiki/Beckhampton_Avenue]; Excavations in 2000 revealed the parallel rows of holes that held the stones [SUPPORTED: https://en.wikipedia.org/wiki/Beckhampton_Avenue]"}]'::jsonb),
    ('fa7e3956-6d81-4cc4-95ce-80e2c06b9f7a'::uuid, 'card_description', 'Neolithic stone tool workshops on Chimei Island, active 3,800-4,500 years ago. Three coastal village sites produced tools across the mid-Neolithic period of prehistoric Taiwan.', 'Around Chimei Island in Penghu County, the Chimei Lithic Workshops hold large amounts of lithics but no complete ones: places where stone was mined and prepared, 3,800 to 4,500 years ago.', 'teaser-card-s021:fa7e3956-6d81-4cc4-95ce-80e2c06b9f7a:card_description', 'teaser-card-s021 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '5cb641dc4cb26ca3659a4d85fcac37b39f6836f513732b107bc04e33ecb253b8|18b9ff3d42f334e85630bcab06a8929ff732018194676c6e9ee93497bcd5d2b8|18b9ff3d42f334e85630bcab06a8929ff732018194676c6e9ee93497bcd5d2b8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Around Chimei Island in Penghu County, the Chimei Lithic Workshops hold large amounts of lithics but no complete ones: places where stone was mined and prepared, 3,800 to 4,500 years ago."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the workshops lie around Chimei Island in Penghu County [S1, S2]; they hold large amounts of lithics [S3]; no complete lithics have been found there [S3]; they were places where stone was mined and prepared [S3]; they date to 3,800 to 4,500 years ago [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Chimei Lithic Workshops were workshops for making stone tools [SUPPORTED: https://en.wikipedia.org/wiki/Chimei_lithic_workshops]; The workshops are located around Chimei Island in Penghu County (Taiwan) [SUPPORTED: https://en.wikipedia.org/wiki/Chimei_lithic_workshops]; The workshops hold large amounts of lithics [SUPPORTED: https://en.wikipedia.org/wiki/Chimei_lithic_workshops]; No complete lithics have been found at the workshops [SUPPORTED: https://en.wikipedia.org/wiki/Chimei_lithic_workshops]; They were places where stone was mined and prepared [SUPPORTED: https://en.wikipedia.org/wiki/Chimei_lithic_workshops]; The workshops date to 3,800 to 4,500 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Chimei_lithic_workshops]"}]'::jsonb),
    ('fbdc7958-5aa3-4197-89fa-77f2a84cc4c9'::uuid, 'card_description', 'The first attempt at a straight-sided pyramid, built around 2620 BC. Its outer casing collapsed in antiquity, leaving a tower-like core rising from a mountain of rubble.', 'The Meidum Pyramid seems never to have been completed. Napoleon''s Expedition found it with its present three steps in 1799, and Flinders Petrie later located its mortuary temple.', 'teaser-card-s021:fbdc7958-5aa3-4197-89fa-77f2a84cc4c9:card_description', 'teaser-card-s021 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'b51f938ea9d7b5b20709cda236e754176221fca5f9c63b180c3e7a9a02d4a22c|97c5d37156907aa8c31523deb2358a0e5c923cafe489586e8f3dc23df143cb36|97c5d37156907aa8c31523deb2358a0e5c923cafe489586e8f3dc23df143cb36', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Meidum Pyramid seems never to have been completed. Napoleon''s Expedition found it with its present three steps in 1799, and Flinders Petrie later located its mortuary temple."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Meidum Pyramid seems never to have been completed [S1]; Napoleon''s Expedition investigated it in 1799 [S2]; it had its present three steps by then [S2]; Flinders Petrie later located its mortuary temple [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Meidum Pyramid is a pyramid at the archaeological site of Meidum in Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Meidum]; The Meidum Pyramid seems never to have been completed [SUPPORTED: https://en.wikipedia.org/wiki/Meidum]; Napoleon''s Expedition came upon the pyramid in 1799 with its present three steps [SUPPORTED: https://en.wikipedia.org/wiki/Meidum]; Flinders Petrie later located the pyramid''s mortuary temple [SUPPORTED: https://en.wikipedia.org/wiki/Meidum]"}]'::jsonb),
    ('fc84c8b7-697c-4ee3-924b-e412f5585c2b'::uuid, 'card_description', 'The Mut Precinct at Karnak contains at least six temples - the Mut Temple, the Contra Temple, and Temples A, B, C, and D. One of four compounds that together form the Karnak Temple Complex.', 'In the Mut Precinct at Luxor, a sacred lake called the Isheru surrounds the Mut Temple on three sides, and statues of the lion-headed goddess Sekhmet were found here.', 'teaser-card-s021:fc84c8b7-697c-4ee3-924b-e412f5585c2b:card_description', 'teaser-card-s021 (teaser-card): teaser card, 166 characters, checked PASS, web-verified VERIFIED', '53bc9289a9bafbc3b2330bfb0a3db105c31015e30438aa51581d82abf9fd853a|e73c86a00eb848af609f34d31ddb9d9109b5610c338ac12c56589127443da0f0|e73c86a00eb848af609f34d31ddb9d9109b5610c338ac12c56589127443da0f0', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Mut Precinct at Luxor, a sacred lake called the Isheru surrounds the Mut Temple on three sides, and statues of the lion-headed goddess Sekhmet were found here."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Mut Precinct is at Luxor [S1]; a sacred lake called the Isheru lies there [S5]; it surrounds the Mut Temple on three sides [S5]; statues of the lion-headed goddess Sekhmet were found there [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Mut Precinct is an Ancient Egyptian temple compound at Luxor [SUPPORTED: https://en.wikipedia.org/wiki/Precinct_of_Mut]; A sacred lake called the Isheru lies in the Mut Precinct [SUPPORTED: https://en.wikipedia.org/wiki/Precinct_of_Mut]; The sacred lake Isheru surrounds the Mut Temple [SUPPORTED: https://en.wikipedia.org/wiki/Precinct_of_Mut]; The lake surrounds the Mut Temple on three sides [SUPPORTED: https://en.wikipedia.org/wiki/Precinct_of_Mut]; Statues of Sekhmet were found at the Mut Precinct [SUPPORTED: https://en.wikipedia.org/wiki/Precinct_of_Mut]; Sekhmet is a lion-headed goddess [SUPPORTED: https://en.wikipedia.org/wiki/Precinct_of_Mut]"}]'::jsonb),
    ('fc973357-2176-4ed3-ab9d-fdb783edb192'::uuid, 'card_description', 'A 4th-century BC walled Iron Age village, a textbook example of Castro culture. Round stone houses sit in tight clusters behind concentric defensive walls.', 'On an east-facing slope, Castro de Borneiro was the first Galician castro to be scientifically dated. Lived in from the 4th to the 1st century BCE, it shows no signs of Romanization.', 'teaser-card-s021:fc973357-2176-4ed3-ab9d-fdb783edb192:card_description', 'teaser-card-s021 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'f1d6299ad9177195c9e563fcc300ce4113d35ae05703e4d3885968e728503bf5|d93c2fef3ca83ef7dfa06cf5bea3889b36160d8dbcc2d0781ef26f85b7cf52c5|d93c2fef3ca83ef7dfa06cf5bea3889b36160d8dbcc2d0781ef26f85b7cf52c5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On an east-facing slope, Castro de Borneiro was the first Galician castro to be scientifically dated. Lived in from the 4th to the 1st century BCE, it shows no signs of Romanization."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies on an east-facing slope [S4]; Castro de Borneiro was the first Galician castro to be scientifically dated [S4]; the site was inhabited from the 4th to the 1st century BCE [S2]; no signs of Romanization have been found at the site [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castro de Borneiro is a castro, an Iron Age walled settlement (oppidum) [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Borneiro]; Castro de Borneiro is in Galicia, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Borneiro]; The castro stands on an east-facing slope [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Borneiro]; It was the first Galician castro to be scientifically dated [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Borneiro]; It was lived in from the 4th to the 1st century BCE [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Borneiro]; No signs of Romanization have been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Borneiro]"}]'::jsonb),
    ('fd8def6a-360b-43ea-be95-f451dca3b19d'::uuid, 'card_description', 'Three concentric earthwork rings — each higher than the last — define this Durotriges hillfort above east Dorset. A Roman-era town known as Vindocladia stood just to the south-west.', 'In east Dorset, 327 feet above sea level, the Iron Age hill fort of Badbury Rings lay in Durotriges territory. A Roman temple stood just west of it, and five Roman roads met to its north.', 'teaser-card-s021:fd8def6a-360b-43ea-be95-f451dca3b19d:card_description', 'teaser-card-s021 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'bca04f2d47016ebf8e8150664b93fb553325ecf46505c2fd2ead1d727ebdaae8|700d67da5d11e1acdf66a860e1c1a47f18ae2063ea08ace105490392090bc6f6|700d67da5d11e1acdf66a860e1c1a47f18ae2063ea08ace105490392090bc6f6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In east Dorset, 327 feet above sea level, the Iron Age hill fort of Badbury Rings lay in Durotriges territory. A Roman temple stood just west of it, and five Roman roads met to its north."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Badbury Rings is in east Dorset [S1]; it sits 327 feet above sea level [S4]; it is an Iron Age hill fort [S1]; it was in the territory of the Durotriges [S2]; in the Roman era a temple stood immediately west of the fort [S3]; five Roman roads met on the north side of Badbury Rings [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Badbury Rings is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Rings]; Badbury Rings is in east Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Rings]; Badbury Rings lies 327 feet above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Rings]; Badbury Rings lay in the territory of the Durotriges [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Rings]; A Roman-era temple stood immediately west of the hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Rings]; Five Roman roads met to the north of Badbury Rings [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Rings]"}]'::jsonb),
    ('fdc3a783-3b1a-473a-bf22-8510308e0054'::uuid, 'card_description', 'Herod built this desert fortress on a man-made mountain, then had himself buried inside it. The palace, bathhouse, and his tomb all survive within the cone-shaped hill.', 'Atop an artificial, cone-shaped hill seen from Jerusalem, Herodion National Park holds Herod''s fortified summit palace. Josephus says Herod was buried here after his death in 4 BCE.', 'teaser-card-s021:fdc3a783-3b1a-473a-bf22-8510308e0054:card_description', 'teaser-card-s021 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'f591587c476fd74b815a09d17927a19b8579c35ea6be3e2f36ca209863b67d21|da3be8ad509ff134139fae831f892c0fb8cf3fa6b3c24b6da3baa34de3e01b12|da3be8ad509ff134139fae831f892c0fb8cf3fa6b3c24b6da3baa34de3e01b12', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Atop an artificial, cone-shaped hill seen from Jerusalem, Herodion National Park holds Herod''s fortified summit palace. Josephus says Herod was buried here after his death in 4 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site stands atop an artificial, cone-shaped hill [S2]; the hill can be seen from Jerusalem [S2]; Herod''s engineers built a fortified palace at the summit [S3]; according to Josephus, Herod was buried at the site [S5]; Herod died in 4 BCE [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Herodion is a fortified palace built by Herod (the central claim: a palace-fortress) [SUPPORTED: https://en.wikipedia.org/wiki/Herodium]; There is a Herodium national park (Herodion National Park) [SUPPORTED: https://en.wikipedia.org/wiki/Herodium]; The site stands atop an artificial, cone-shaped hill [SUPPORTED: https://en.wikipedia.org/wiki/Herodium]; The hill can be seen from Jerusalem [SUPPORTED: https://en.wikipedia.org/wiki/Herodium]; Herod''s fortified palace stands at the summit [SUPPORTED: https://en.wikipedia.org/wiki/Herodium]; Josephus says Herod was buried at Herodium after his death in 4 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Herodium]"}]'::jsonb),
    ('fdeca69b-4a68-455c-a865-044b37ccfd21'::uuid, 'card_description', 'A site with finds stretching back over 10,000 years, including Paleolithic through Iron Age layers. Its elevated position dominated the bay and served as a natural lookout.', 'Ploughing on Warren Hill in 1913 revealed thousands of flint implements. The hill also gave up blades rarely seen in the UK outside of caves, typical of Upper Paleolithic sites in Europe.', 'teaser-card-s021:fdeca69b-4a68-455c-a865-044b37ccfd21:card_description', 'teaser-card-s021 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'f8ba2c1070c1b2bd017f6a0cb6ffa2f86afaa1adde16588cab1f00ca699b4751|5f90a4ce732a5ab4df48d1a2d6ddba59f87d95b83b4e6a52837cf98e9e01bc41|5f90a4ce732a5ab4df48d1a2d6ddba59f87d95b83b4e6a52837cf98e9e01bc41', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ploughing on Warren Hill in 1913 revealed thousands of flint implements. The hill also gave up blades rarely seen in the UK outside of caves, typical of Upper Paleolithic sites in Europe."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "ploughing of Warren Hill in 1913 revealed flint implements [S4]; the flint implements numbered thousands [S4]; the hill yielded blades rarely seen in the UK outside of caves [S5]; such blades are typical of Upper Paleolithic sites in Europe [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Warren Hill is the elevated part of Hengistbury Head, an archaeological site in Dorset, England [SUPPORTED: https://en.wikipedia.org/wiki/Warren_Hill,_Bournemouth]; Ploughing of Warren Hill in 1913 revealed thousands of flint implements [SUPPORTED: https://en.wikipedia.org/wiki/Warren_Hill,_Bournemouth]; The hill yielded blades rarely seen in the UK outside of caves [SUPPORTED: https://en.wikipedia.org/wiki/Warren_Hill,_Bournemouth]; Such blades are typical of Upper Paleolithic sites across Europe [SUPPORTED: https://en.wikipedia.org/wiki/Warren_Hill,_Bournemouth]"}]'::jsonb),
    ('fe663edf-4b9e-480b-a976-c8ecf135249d'::uuid, 'card_description', 'Aihole, along with nearby Badami, emerged by the 6th century as the cradle of experimentation with temple architecture, stone artwork, and construction techniques.', 'Over 120 stone and cave temples spread along the Malaprabha river valley at Aihole. With nearby Badami, it emerged by the 6th century as a cradle of experiment in temple architecture.', 'teaser-card-s021:fe663edf-4b9e-480b-a976-c8ecf135249d:card_description', 'teaser-card-s021 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'c0502bf49db3e130e051012c58b5f74cd7a51f2a9d8bc61afbce5e937242f4d8|c410d6b0854c3bb55d7c254c6e7fe57a3644c9f12b1a6d7360ac8ab5c288f904|c410d6b0854c3bb55d7c254c6e7fe57a3644c9f12b1a6d7360ac8ab5c288f904', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Over 120 stone and cave temples spread along the Malaprabha river valley at Aihole. With nearby Badami, it emerged by the 6th century as a cradle of experiment in temple architecture."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Aihole has over 120 stone and cave temples [S2]; the temples are spread along the Malaprabha river valley [S2]; Aihole together with nearby Badami emerged by the 6th century as a cradle of experimentation in temple architecture [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Aihole is a historic site of Buddhist, Hindu and Jain monuments (temples) in Karnataka, India [SUPPORTED: https://en.wikipedia.org/wiki/Aihole]; Aihole has over 120 stone and cave temples spread along the Malaprabha river valley [SUPPORTED: https://en.wikipedia.org/wiki/Aihole]; With nearby Badami, Aihole emerged by the 6th century as a cradle of experimentation with temple architecture [SUPPORTED: https://en.wikipedia.org/wiki/Aihole]"}]'::jsonb),
    ('fe6b3da9-80c2-4692-a859-cd645550fabd'::uuid, 'card_description', 'Nearly square in plan with 9 bastions, this castle in Mut was built over the area of the Roman city of Claudiopolis. A cylindrical inner keep at its core suggests earlier Byzantine-era construction.', 'Around Mut Castle, of face stone and rubble stone, lay Roman Claudiupolis. Kayqubad I of the Sultanate of Rum took and rebuilt the castle in 1225; the Ottoman Empire seized it in 1473.', 'teaser-card-s021:fe6b3da9-80c2-4692-a859-cd645550fabd:card_description', 'teaser-card-s021 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'bc22ee306c837834408600774bb21df259bd6f8aef814d88050afd83e02f10bb|fac72936409c24781fc2cf5ceb42a076eb3456b6fc75036f54451375b62e480f|fac72936409c24781fc2cf5ceb42a076eb3456b6fc75036f54451375b62e480f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Around Mut Castle, of face stone and rubble stone, lay Roman Claudiupolis. Kayqubad I of the Sultanate of Rum took and rebuilt the castle in 1225; the Ottoman Empire seized it in 1473."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "face stone and rubble stone were used in the castle''s construction [S5]; during the Roman Empire the neighbourhood around the castle was known as Claudiupolis [S2]; in 1225 the Sultanate of Rum under Kayqubad I captured the castle [S3]; in 1225 the Sultanate of Rum under Kayqubad I rebuilt the castle [S3]; in 1473 the Ottoman Empire captured the castle [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mut Castle is a castle (fortification) in Mut, Mersin Province, Turkiye [SUPPORTED: https://en.wikipedia.org/wiki/Mut_Castle]; The neighbourhood around Mut Castle was Roman Claudiupolis [SUPPORTED: https://en.wikipedia.org/wiki/Mut_Castle]; The castle was built of face stone and rubble stone [SUPPORTED: https://en.wikipedia.org/wiki/Mut_Castle]; Kayqubad I of the Sultanate of Rum took the castle and rebuilt it in 1225 [SUPPORTED: https://en.wikipedia.org/wiki/Mut_Castle]; The Ottoman Empire seized the castle in 1473 [SUPPORTED: https://en.wikipedia.org/wiki/Mut_Castle]"}]'::jsonb),
    ('fe7c453a-cabe-4fb2-9009-2ed71a7632fd'::uuid, 'card_description', 'A timber and stone ritual site connected to Avebury via the West Kennet Avenue. Originally 58 stone sockets and 62 post-holes formed concentric circles here.', 'On Overton Hill the Sanctuary began around 3000 BCE as a ring of eight wooden posts. The West Kennet Avenue joined it to Avebury; local farmers destroyed its stones in the 1720s.', 'teaser-card-s021:fe7c453a-cabe-4fb2-9009-2ed71a7632fd:card_description', 'teaser-card-s021 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '1f60505951fc4013950a94f4d7dde5c6ac28c266d6dbe4ca466fcc06bbd0658e|a7c4a726240664133a463ebee12d168dc3919b5372e253aa2a481cc9b9b17a22|a7c4a726240664133a463ebee12d168dc3919b5372e253aa2a481cc9b9b17a22', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Overton Hill the Sanctuary began around 3000 BCE as a ring of eight wooden posts. The West Kennet Avenue joined it to Avebury; local farmers destroyed its stones in the 1720s."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Sanctuary stands on Overton Hill [S3]; its first stage of activity was around 3000 BCE [S7]; the first stage was a ring of eight wooden posts [S7]; the West Kennet Avenue connected the Sanctuary to Avebury [S4]; local farmers destroyed the stones [S5]; the stones were destroyed in the 1720s [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Sanctuary is a stone and timber circle near Avebury in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/The_Sanctuary]; The Sanctuary stands on Overton Hill [SUPPORTED: https://en.wikipedia.org/wiki/The_Sanctuary]; It began around 3000 BCE [SUPPORTED: https://en.wikipedia.org/wiki/The_Sanctuary]; Its first form was a ring of eight wooden posts [SUPPORTED: https://en.wikipedia.org/wiki/The_Sanctuary]; The West Kennet Avenue joined the Sanctuary to Avebury [SUPPORTED: https://en.wikipedia.org/wiki/The_Sanctuary]; Local farmers destroyed its stones in the 1720s [SUPPORTED: https://en.wikipedia.org/wiki/The_Sanctuary]"}]'::jsonb),
    ('fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a'::uuid, 'card_description', 'A 600 km tourism route linking the birthplaces and estates of 18 Roman emperors. More Roman emperors came from this region than any other outside Italy.', NULL, 'teaser-card-s021:fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a:card_description', 'teaser-card-s021 (card-clear-contradicted-after-verify): card cleared (contradicted-after-verify)', '||0c19068e913a41dbe338b12ed8322fb705a5de00b227ec788748ff4e3a6b6e01', '[{"source": "lane WB run wb-ws-2026-09-27-06: contradicted-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The web check could not prove: The Roman Emperors Route is a tourism and archaeology project in Serbia, a route linking ancient Roman sites; The web check could not prove: 17 Roman emperors were born within the current borders of Serbia; The web check contradicts: Felix Romuliana is an important Roman city (https://whc.unesco.org/en/list/1253: \"The Late Roman fortified palace compound and memorial complex of Gamzigrad-Romuliana, Palace of Galerius\")"}]'::jsonb),
    ('ff53d37c-ab2b-4874-8ed8-a3336ccd12fc'::uuid, 'card_description', 'A Late Minoan tholos tomb from around the 14th–13th century BC on ''Kafkala'' hill near Maleme. Corbelled beehive vaults like this required each stone ring to be set smaller than the last.', 'On Kafkala hill near Maleme, a corridor 25.10m long leads into a Late Minoan tholos tomb. Looted at the beginning of the 20th century, it lost part of its roof to a World War II bomb.', 'teaser-card-s021:ff53d37c-ab2b-4874-8ed8-a3336ccd12fc:card_description', 'teaser-card-s021 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '00cf110e81443c05fc92c5233aa4cda8781fc10ee5ff8cedc749aafbe66be63c|7b56f53c5aafa5990a4ddffde4e2bd1b4242f1cf09f5448934a8268e200e99a8|7b56f53c5aafa5990a4ddffde4e2bd1b4242f1cf09f5448934a8268e200e99a8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Kafkala hill near Maleme, a corridor 25.10m long leads into a Late Minoan tholos tomb. Looted at the beginning of the 20th century, it lost part of its roof to a World War II bomb."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the tomb is on Kafkala hill [S2]; the tomb is near Maleme [S1]; a corridor (dromos) 25.10 m long leads to the chamber [S5]; it is a Late Minoan tholos tomb [S1]; it was looted at the beginning of the 20th century [S2]; a World War II bomb partially destroyed its roof [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The site is a tholos tomb in the vicinity of Maleme (Crete, Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Maleme]; The tomb is Late Minoan [SUPPORTED: https://en.wikipedia.org/wiki/Maleme]; The tomb is on Kafkala hill [SUPPORTED: https://en.wikipedia.org/wiki/Maleme]; A corridor (dromos) 25.10 m long leads into the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Maleme]; The tomb was looted at the beginning of the 20th century [SUPPORTED: https://en.wikipedia.org/wiki/Maleme]; A World War II bomb destroyed part of the tomb''s roof [SUPPORTED: https://en.wikipedia.org/wiki/Maleme]"}]'::jsonb),
    ('ff824fd2-59cd-49dc-ad4f-21c437f20189'::uuid, 'card_description', 'A twin-peaked Iron Age hillfort enclosing 4.9 hectares, the tribal center of the Votadini. Its stone wall encircles the summit at 353 meters above sea level.', 'A stone wall upwards of 10 ft thick encircles the summit of Yeavering Bell, a twin-peaked hill where the Votadini had a tribal centre. Remains of stone huts are scattered over its sides.', 'teaser-card-s021:ff824fd2-59cd-49dc-ad4f-21c437f20189:card_description', 'teaser-card-s021 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'dcfc52395252eac04a4e2b5608059cef244dbb3979984d837b3842a65facef7e|49e7482528737b6ef3c436a2b135403562a8688c650c40b3ef29a6534c44257b|49e7482528737b6ef3c436a2b135403562a8688c650c40b3ef29a6534c44257b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A stone wall upwards of 10 ft thick encircles the summit of Yeavering Bell, a twin-peaked hill where the Votadini had a tribal centre. Remains of stone huts are scattered over its sides."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "a stone wall upwards of 10 ft thick encloses the hillfort [S3]; the wall encircles the summit [S2]; Yeavering Bell is a twin-peaked hill [S1]; the hillfort was a tribal centre of the Votadini [S2]; remains of stone huts lie on the sides of the hill [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Yeavering Bell is a twin-peaked hill in Northumberland, England, crowned by a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Yeavering_Bell]; A wall encircles the summit [SUPPORTED: https://en.wikipedia.org/wiki/Yeavering_Bell]; The wall is of stone and upwards of 10 ft thick [SUPPORTED: https://en.wikipedia.org/wiki/Yeavering_Bell]; The hill was a tribal centre of the Votadini [SUPPORTED: https://en.wikipedia.org/wiki/Yeavering_Bell]; Remains of stone huts are scattered over the hill''s sides [SUPPORTED: https://en.wikipedia.org/wiki/Yeavering_Bell]"}]'::jsonb),
    ('ffb9aa8c-0ecc-4510-b18d-8555e319c427'::uuid, 'card_description', '3300-500 BC Bronze Age settlement clusters on Bodmin Moor at 329 metres. Two settlement areas on the slopes hold field enclosures, cairns, a cist, a propped stone, and associated stone circles.', 'Leskernick Hill stands 329m high on Bodmin Moor. On its south and western slopes lie 2 Bronze Age settlements, with field enclosures, small cairns, a cist and a propped stone.', 'teaser-card-s021:ffb9aa8c-0ecc-4510-b18d-8555e319c427:card_description', 'teaser-card-s021 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '612c9634618b080f321f6816037bb83740ceafd504f42c16f569b11455b69a6a|f6121b3f1cac468b18e2e44ed6a29fa3f05d6b827f993f34e5f6e52755f39149|f6121b3f1cac468b18e2e44ed6a29fa3f05d6b827f993f34e5f6e52755f39149', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Leskernick Hill stands 329m high on Bodmin Moor. On its south and western slopes lie 2 Bronze Age settlements, with field enclosures, small cairns, a cist and a propped stone."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Leskernick Hill is 329 m high [S2]; it is on Bodmin Moor [S1]; on its south and western slopes are 2 Bronze Age settlements [S3]; the settlements have associated field enclosures, small cairns, a cist and a propped stone [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Leskernick Hill is a hill on Bodmin Moor (in Cornwall, England), with Bronze Age settlement remains on it [SUPPORTED: https://en.wikipedia.org/wiki/Leskernick_Hill]; The hill stands 329m high [SUPPORTED: https://en.wikipedia.org/wiki/Leskernick_Hill]; On its south and western slopes lie 2 Bronze Age settlements [SUPPORTED: https://en.wikipedia.org/wiki/Leskernick_Hill]; The settlements have associated field enclosures [SUPPORTED: https://www.wikidata.org/wiki/Q97384369]; Small cairns lie among the settlements [SUPPORTED: https://en.wikipedia.org/wiki/Leskernick_Hill]; A cist lies among the settlements [SUPPORTED: https://www.wikidata.org/wiki/Q97384369]; There is a propped stone on the hill [SUPPORTED: https://www.wikidata.org/wiki/Q97384369]"}]'::jsonb),
    ('ffd325ad-d579-4510-90c7-acb87b753c88'::uuid, 'card_description', 'The site was built in layers, with the earliest C14 date from the cairn determined at 3845 ± 85 radiocarbon years before present.', 'On a grassy hill above the Bow River prairie, the Majorville Cairn and Medicine Wheel links a round stone cairn to a cobble circle by 28 stone spokes, and yielded buffalo calling stones.', 'teaser-card-s021:ffd325ad-d579-4510-90c7-acb87b753c88:card_description', 'teaser-card-s021 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '22fa6c59956acca50e2565e372b3baa34eaf2bed6bbcb0f5461714650a62c7b2|769e3ed31bd0e1811b2cf639fc68404e4f3adbc3ddaa236e1b9ac072b62da96c|769e3ed31bd0e1811b2cf639fc68404e4f3adbc3ddaa236e1b9ac072b62da96c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a grassy hill above the Bow River prairie, the Majorville Cairn and Medicine Wheel links a round stone cairn to a cobble circle by 28 stone spokes, and yielded buffalo calling stones."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the medicine wheel sits on a grassy hill [S2]; the hill overlooks the prairie around the Bow River [S2]; a round stone cairn is connected to a cobble circle by 28 stone spokes [S3]; the site yielded iniskim stones, also called buffalo calling stones [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Majorville Cairn and Medicine Wheel is an archaeological site (a medicine wheel) of the Blackfoot Nation in southern Alberta, Canada [SUPPORTED: https://en.wikipedia.org/wiki/Majorville_Cairn_and_Medicine_Wheel_site]; The medicine wheel stands on a grassy hill [SUPPORTED: https://en.wikipedia.org/wiki/Majorville_Cairn_and_Medicine_Wheel_site]; The hill overlooks the prairie around the Bow River [SUPPORTED: https://en.wikipedia.org/wiki/Majorville_Cairn_and_Medicine_Wheel_site]; The structure has a round stone cairn [SUPPORTED: https://en.wikipedia.org/wiki/Majorville_Cairn_and_Medicine_Wheel_site]; The cairn is linked to a cobble circle by 28 stone spokes [SUPPORTED: https://en.wikipedia.org/wiki/Majorville_Cairn_and_Medicine_Wheel_site]; The site yielded buffalo calling stones (iniskim) [SUPPORTED: https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=15835]"}]'::jsonb),
    ('fffac2f9-3115-47be-9830-f5969cce734b'::uuid, 'card_description', 'A 1000 BC burial mound 7 metres high and 45 metres across — Scandinavia''s most gold-rich Bronze Age grave. The mound was built of turf over a cairn, once at the sea''s edge.', 'Under the turf and cairn of the Håga Mound, a wooden chamber held a hollow oak coffin with the cremated remains of a short man: Scandinavia''s most gold-rich Bronze Age grave ever found.', 'teaser-card-s021:fffac2f9-3115-47be-9830-f5969cce734b:card_description', 'teaser-card-s021 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '63ba8627a3e7927369a215ce047163d1887926a1d620da38db11ae6620d4598f|123781d93a953c6cea4e7112a78a0361c73031e3e49ad28b72bcd1e32207663c|123781d93a953c6cea4e7112a78a0361c73031e3e49ad28b72bcd1e32207663c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Under the turf and cairn of the Håga Mound, a wooden chamber held a hollow oak coffin with the cremated remains of a short man: Scandinavia''s most gold-rich Bronze Age grave ever found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the mound was built of turfs laid on top of a cairn [S6]; the cairn was built on top of a wooden chamber [S7]; the chamber contains a hollow oak coffin [S7]; the coffin holds the cremated remains of a short man [S8]; it is Scandinavia''s most gold-rich Bronze Age grave ever found [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Håga Mound is a Bronze Age burial mound (tumulus) in Sweden, at Uppsala [SUPPORTED: https://en.wikipedia.org/wiki/H%C3%A5ga_mound]; The mound is built of turf laid on top of a cairn [SUPPORTED: https://en.wikipedia.org/wiki/H%C3%A5ga_mound]; Under the cairn lay a wooden chamber [SUPPORTED: https://en.wikipedia.org/wiki/H%C3%A5ga_mound]; The wooden chamber held a hollow oak coffin [SUPPORTED: https://en.wikipedia.org/wiki/H%C3%A5ga_mound]; The coffin held cremated remains [SUPPORTED: https://en.wikipedia.org/wiki/H%C3%A5ga_mound]; The cremated remains were those of a short man [SUPPORTED: https://en.wikipedia.org/wiki/H%C3%A5ga_mound]; It is Scandinavia''s most gold-rich Bronze Age grave ever found [SUPPORTED: https://historiska.se/en/explore-history/history-hub/the-haga-mound/]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 48;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s021', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s021'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s021'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 48 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s021'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
